// --- Rose Pine design tokens, generated by Style Dictionary in theme/ ---
// (`theme/build/android/colors.xml` + `theme/build/android/Theme.kt`, Phase 1).
// launcher/ must not redefine or duplicate any color value, so the app module
// reads those generated outputs directly instead of vendoring copies.
val themeAndroidOutputDir = rootProject.projectDir.resolve("../theme/build/android")

// AAPT only recognizes resource files inside a qualifier directory (values/,
// drawable/, ...), but Style Dictionary writes colors.xml flat into
// theme/build/android/. Sync the one resource file we need into a generated
// `values/` folder at build time and register that as an extra res dir, so
// no color values are hand-copied into this repo — only mechanically synced
// from the single generated source of truth.
val syncThemeColors = tasks.register<Sync>("syncThemeColors") {
    from(themeAndroidOutputDir) {
        include("colors.xml")
    }
    into(layout.buildDirectory.dir("generated/rosePineTheme/res/values"))
}

android {
    namespace = "dev.rileyboughner.launcher"
    compileSdk = 34

    defaultConfig {
        applicationId = "dev.rileyboughner.launcher"
        minSdk = 26
        targetSdk = 34
        versionCode = 1
        versionName = "0.1.0-skeleton"
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = "17"
    }

    buildFeatures {
        compose = true
    }

    sourceSets {
        getByName("main") {
            // Theme.kt (package platform.theme, object PlatformTheme) lives
            // directly in theme/build/android/. Kotlin source sets, unlike
            // Java's, don't require the directory layout to mirror the
            // package name, so this file can be compiled straight out of
            // the generated theme output with no copy and no symlink.
            kotlin.srcDir(themeAndroidOutputDir)

            // Generated values/colors.xml from the Sync task above.
            res.srcDir(layout.buildDirectory.dir("generated/rosePineTheme/res"))
        }
    }
}

tasks.named("preBuild") {
    dependsOn(syncThemeColors)
}

// Resource merging also needs to run after the sync, for correctness when
// someone invokes a *ResValues/*Resources task directly instead of assemble.
tasks.matching { it.name.contains("Resources") || it.name.contains("ResValues") }.configureEach {
    dependsOn(syncThemeColors)
}

